/* ==================== Экспорт в PDF (через печать) ==================== */
function buildExportTable(title, section) {
  const rows = sections[section]
    .map((item) => [item.name, item.code, counts[countKey(section, item)] || 0, !!checked[countKey(section, item)]])
    .filter(([, , qty]) => qty > 0);
  if (rows.length === 0) return "";
  const rowsHtml = rows.map(([name, code, qty]) =>
    `<tr><td>${escapeHtml(name)}</td><td>${code ? escapeHtml(code) : "—"}</td><td style="text-align:center">${qty}</td></tr>`
  ).join("");
  return `
    <h3>${title}</h3>
    <table>
      <thead><tr><th>Наименование</th><th style="width:130px;">Код</th><th style="width:70px;">Кол-во</th></tr></thead>
      <tbody>${rowsHtml}</tbody>
    </table>`;
}
function runConsumptionExport() {
  const partsHtml = buildExportTable("Детали", "parts");
  const consumHtml = buildExportTable("Расходники", "consumables");
  if (!partsHtml && !consumHtml) {
    alert("За выбранную дату ещё нет выданных позиций (все счётчики равны 0).");
    return;
  }
  const printArea = document.getElementById("printArea");
  printArea.innerHTML = `
    <h1>Учёт потребления деталей</h1>
    <div class="print-date">Дата: ${escapeHtml(formatFull(currentDate))}</div>
    ${partsHtml}
    ${consumHtml}
  `;
  window.print();
}

/* ==================== ВКЛАДКА СКЛАД: логика ==================== */
/* ==================== Фильтр склада по модели ====================
   Всё / YGW 5.0 / YGW 4.0 / 9Bot. Только просмотр: данные не меняются,
   синхронизация не запускается, выбор запоминается на устройстве. */
const WH_FILTER_KEY = "potreblenie_wh_filter_v1";
let whFilterModel = (function () {
  try { return localStorage.getItem(WH_FILTER_KEY) || "all"; } catch (e) { return "all"; }
})();
function saveWhFilter() {
  try { localStorage.setItem(WH_FILTER_KEY, whFilterModel); } catch (e) {}
}
// Пары { item, i } — исходный индекс нужен, иначе кнопки в строках стали бы
// указывать не на те позиции.
function whFilteredPairs(section) {
  const pairs = warehouse[section].map((item, i) => ({ item, i }));
  if (whFilterModel === "all") return pairs;
  return pairs.filter(({ item }) => (item.model || "") === whFilterModel);
}
function renderWarehouseSection(section) {
  // Индекс код→позиция должен быть свежим ДО построения строк: иначе после
  // сортировки/добавления/редактирования (которые меняют порядок или состав
  // массива, но не всегда идут через renderWarehouseAll/renderOneCAll) тут
  // читался бы старый индекс — переход между «Складом» и «1С» и колонки
  // сравнения/остатка указывали бы не на ту позицию.
  rebuildCrossIndexes();
  const tbody = document.getElementById("wh-body-" + section);
  const picked = selectedWH[section];
  tbody.innerHTML = whFilteredPairs(section).map(({ item, i }) => {
    const key = countKey(section, item);
    const ocInfo = oneCInfoFor(item.code);
    return `<tr data-key="${escapeHtml(key)}" data-index="${i}"${picked.has(key) ? ' class="row-picked"' : ""}>
      <td class="num">${i + 1}</td>
      <td class="code wh-code">${item.code ? `<span class="code-text" data-code="${escapeHtml(item.code)}">${formatCodeDisplay(item.code)}</span>` : "—"}${item.model ? `<span class="wh-model-badge">${escapeHtml(item.model)}</span>` : ""}</td>
      <td class="name"><div class="main-name">${escapeHtml(item.name)}</div>${ocInfo ? altNameHtml(item.code, ocInfo, true) : ""}</td>
      <td class="count-merged wh-merged">
        <div class="count-tier count-tier-num">
          <input type="number" min="0" value="${item.qty || 0}" class="whQtyInput"
            data-section="${section}" data-index="${i}">
        </div>
        <div class="count-tier count-tier-oc">${ocInfo ? ocInfo.qty : "—"}</div>
      </td>
      <td class="buttons wh-buttons">
        <div class="menu-wrap wh-menu-wrap">
          <button class="iconbtn wh-menu-btn" data-section="${section}" data-index="${i}" title="Действия">⋮</button>
          <div class="menu-panel wh-menu-panel">
            <button class="wh-edit" data-section="${section}" data-index="${i}" title="Редактировать">✎</button>
            <button class="wh-history" data-section="${section}" data-index="${i}" title="История выдачи">🕘</button>
            <button class="wh-print" data-section="${section}" data-index="${i}" title="Печать этикеток">🖨️</button>
            <button class="wh-del danger" data-section="${section}" data-index="${i}" title="Удалить со склада">✕</button>
          </div>
        </div>
      </td>
    </tr>`;
  }).join("");
  updateWarehouseTotals(section);
  if (typeof applyWhSearch === "function") applyWhSearch();
}
function renderWarehouseAll() {
  rebuildCrossIndexes();
  renderWarehouseSection("parts");
  renderWarehouseSection("consumables");
  updateWhFilterUI();
}
/* Общая для «Склада» и «1С»: прячет пустой после фильтра раздел (таблицу и
   заголовок), кроме шапки с кнопкой фильтра — иначе из режима, где раздел
   пуст, нельзя было бы переключиться обратно. Заголовок раздела — только
   элемент прямо перед таблицей: идти назад «до первого .section-head»
   нельзя, у «Расходников» заголовок — простой h2, и поиск добирался бы до
   шапки «Деталей», пряча её вместе с кнопкой фильтра. */
function hideEmptySections(bodyPrefix, filterBtnId) {
  ["parts", "consumables"].forEach((section) => {
    const tbody = document.getElementById(bodyPrefix + section);
    if (!tbody) return;
    const empty = tbody.children.length === 0;
    const table = tbody.closest(".table-scroll");
    if (table) table.style.display = empty ? "none" : "";
    const head = table ? table.previousElementSibling : null;
    const hasFilter = head && head.querySelector && head.querySelector("#" + filterBtnId);
    if (head && !hasFilter &&
        (head.classList.contains("section-head") || head.classList.contains("section-title"))) {
      head.style.display = empty ? "none" : "";
    }
  });
}
function updateWhFilterUI() {
  const label = document.getElementById("whFilterLabel");
  if (label) {
    const shown = whFilteredPairs("parts").length + whFilteredPairs("consumables").length;
    label.textContent = (whFilterModel === "all" ? "Все" : whFilterModel) + " · " + shown;
  }
  document.querySelectorAll("#whFilterPanel [data-model]").forEach((b) => {
    b.classList.toggle("primary", b.dataset.model === whFilterModel);
  });
  hideEmptySections("wh-body-", "whFilterBtn");
}
