document.getElementById("ocImportRun").addEventListener("click", () => {
  let rows;
  if (ocImportFileRows && ocImportFileRows.length) {
    rows = ocImportFileRows;
  } else {
    const raw = document.getElementById("ocImportArea").value.trim();
    if (!raw) { alert("Выберите файл .xlsx или вставьте строки из Excel."); return; }
    rows = parseExcelRows(raw);
  }
  if (!rows || rows.length === 0) { alert("Не удалось распознать ни одной строки."); return; }

  // Сопоставление: КОД в приоритете. Позицию, уже занятую совпадением по
  // коду, нельзя переопределить более поздней строкой с тем же названием —
  // иначе одноимённые детали разных моделей (например «Main Cable» под
  // Wind 4.0 и 5.0) перетирали бы остатки друг друга.
  const claimed = new Set();
  const pending = [];
  let updated = 0, added = 0;
  const byName = [];
  rows.forEach((r) => {
    if (!r.code) { byName.push(r); return; }
    const found = findOcItemByCode(r.code);
    if (found) {
      const key = found.section + "|" + found.index;
      if (!claimed.has(key)) {
        claimed.add(key); updated++;
        pending.push({ type: "update", found, qty: r.qty });
        return;
      }
    }
    byName.push(r);
  });
  byName.forEach((r) => {
    const found = findOcItemByName(r.name);
    const key = found ? (found.section + "|" + found.index) : null;
    if (found && !claimed.has(key)) {
      claimed.add(key); updated++;
      pending.push({ type: "update", found, qty: r.qty });
    } else {
      added++; pending.push({ type: "add", row: r });
    }
  });
  // Позиции, которых в свежей выгрузке нет вообще: 1С не выводит их, когда
  // остаток нулевой. Раньше они оставались со старым числом — например
  // «Задний барабан (Wind 5.0)» так и висел с 20 штуками, хотя в 1С уже 0.
  const zeroed = [];
  ["parts", "consumables"].forEach((section) => {
    onec[section].forEach((it, index) => {
      const key = section + "|" + index;
      if (claimed.has(key)) return;          // позиция была в файле — уже обновлена
      if ((it.qty || 0) === 0) return;       // и так ноль, трогать нечего
      zeroed.push({ section, index, name: it.name, was: it.qty });
    });
  });

  // Страховка от неполной выгрузки: если обнулять пришлось бы больше
  // половины позиций с остатком — почти наверняка отчёт выгружен с
  // отбором (по группе, складу или товару), а не по всей номенклатуре.
  // Такой импорт молча обнулил бы почти весь список.
  const withStock = ["parts", "consumables"]
    .reduce((n, s) => n + onec[s].filter((it) => (it.qty || 0) > 0).length, 0);
  const suspicious = withStock > 0 && zeroed.length > withStock / 2;
  if (suspicious) {
    const ok = confirm(
      `⚠️ Похоже, выгрузка неполная.\n\n` +
      `В файле ${rows.length} строк, а обнулить пришлось бы ${zeroed.length} из ${withStock} позиций с остатком.\n\n` +
      `Обычно так бывает, когда отчёт выгружен с отбором — по группе, складу или конкретному товару, а не по всей номенклатуре.\n\n` +
      `Импортировать только остатки из файла, НЕ обнуляя остальные?`
    );
    if (!ok) return;
    zeroed.length = 0;      // обнуление отменяем, обновляем только то, что в файле
  }

  const zeroMsg = zeroed.length
    ? `\n\nЕщё ${zeroed.length} поз. есть в списке, но отсутствуют в файле — их остаток будет обнулён.`
    : "";
  if (!confirm(`Импорт: обновить остаток у ${updated} поз., добавить новых в 1С — ${added}.${zeroMsg}\n\nСклад не изменится. Продолжить?`)) return;

  pushOcHistory();
  pending.forEach((p) => {
    if (p.type === "update") {
      onec[p.found.section][p.found.index].qty = p.qty;   // только остаток
    } else {
      const item = { code: p.row.code, name: p.row.name, qty: p.row.qty };
      const model = detectModelFromName(p.row.name);
      if (model) item.model = model;
      onec.parts.push(item);
    }
  });
  zeroed.forEach((z) => { onec[z.section][z.index].qty = 0; });
  saveOneC();
  renderOneCAll();
  closeOcImport();
  alert(`Готово: обновлено ${updated}, добавлено ${added}` + (zeroed.length ? `, обнулено ${zeroed.length}` : "") + ".");
});

/* ==================== Импорт количеств на склад ====================
   Простой режим: в файле только код и количество. Обновляем количество у
   совпавших по коду позиций, ничего больше не трогаем — ни названия, ни
   разделы, ни модели. Позиции, которых нет в файле, остаются как есть
   (в отличие от импорта в 1С, где отсутствие означает нулевой остаток). */
let whImportRows = null;
/* Простой разбор таблицы для склада: два столбца — код и количество.
   Отдельно от разбора выгрузки 1С, где своя структура с заголовками.
   Строка-заголовок («Код», «Количество») распознаётся и пропускается. */
async function parseSimpleXlsx(file) {
  const rows = await readXlsxGrid(file);
  const out = [];
  rows.forEach((cells) => {
    const keys = Object.keys(cells).map(Number).sort((a, b) => a - b);
    if (keys.length === 0) return;
    const code = String(cells[keys[0]] || "").trim();
    if (!code) return;
    // второй непустой столбец — количество
    let qty = 0;
    for (let k = 1; k < keys.length; k++) {
      const raw = String(cells[keys[k]] || "").replace(/\s|\u00a0/g, "").replace(",", ".");
      if (raw === "") continue;
      const n = parseFloat(raw);
      if (!isNaN(n)) { qty = Math.max(0, Math.round(n)); }
      break;
    }
    // пропускаем заголовок вида «Код | Количество»
    if (/^(код|артикул)$/i.test(code)) return;
    out.push({ code, qty });
  });
  return out;
}
function findWhItemByCode(code) {
  if (!code) return null;
  const want = codeVariants(code);
  for (const section of ["parts", "consumables"]) {
    const list = warehouse[section];
    for (let i = 0; i < list.length; i++) {
      if (list[i].code && codeVariants(list[i].code).some((v) => want.includes(v))) {
        return { section, index: i };
      }
    }
  }
  return null;
}
